/**
 * Mobile passwordless email sign-in and native registration.
 *
 * REAL DATABASE, REAL CODES, REAL LIMITS. Nothing about the security logic is
 * mocked: the codes are generated by the production path, hashed by it, and
 * verified by it. Stubbing any of that would leave the attempt ceiling and the
 * single-use guarantee — the only things making a 6-digit secret defensible —
 * completely untested.
 *
 * The email SENDER is the one thing replaced, because delivering mail is not the
 * property under test and a test suite must not send any.
 */
import { vi } from 'vitest'

vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
  revalidateTag: vi.fn(),
  cacheTag: vi.fn(),
  unstable_cache: vi.fn((fn: unknown) => fn),
}))
vi.mock('next/navigation', () => ({ redirect: vi.fn(), notFound: vi.fn() }))
vi.mock('next/headers', () => ({
  cookies: vi.fn(() => ({ get: vi.fn(() => null), set: vi.fn(), delete: vi.fn() })),
  headers: vi.fn(() => ({ get: vi.fn(() => null) })),
}))

/** Captures what would have been emailed so the test can read the code back. */
const sentEmails: { to: string; html: string }[] = []
vi.mock('@/lib/email/sender', () => ({
  sendEmail: vi.fn(async ({ to, html }: { to: string; html: string }) => {
    sentEmails.push({ to, html })
    return { ok: true }
  }),
}))

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest'
import { db } from '@/config/db'
import { MAX_CODE_ATTEMPTS } from '@/lib/mobile/rateLimit'

const AGENCY = 960_001
const USER_OK = 961_001
const USER_SUSPENDED = 961_002

const EMAIL_OK = 'mobile.code.ok@example.test'
const EMAIL_SUSPENDED = 'mobile.code.suspended@example.test'
const EMAIL_STRANGER = 'mobile.code.stranger@example.test'
const EMAIL_NEW_TENANT = 'brand.new.tenant@example.test'

async function post(path: string, body: unknown) {
  const { POST } = (await import(`@/app/api/mobile/v1/auth/${path}/route`)) as {
    POST: (r: Request) => Promise<Response>
  }
  const res = await POST(
    new Request(`https://example.test/api/mobile/v1/auth/${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-platform': 'ios' },
      body: JSON.stringify(body),
    }),
  )
  const text = await res.text()
  return { status: res.status, body: text.length > 0 ? JSON.parse(text) : null }
}

/** Reads the code out of the captured email — never out of the database. */
function lastCodeFor(email: string): string {
  const mail = [...sentEmails].reverse().find((m) => m.to === email)
  if (!mail) throw new Error(`no email captured for ${email}`)
  const match = mail.html.match(/>(\d{6})</)
  if (!match) throw new Error('no 6-digit code in email body')
  return match[1]
}

async function clearThrottle() {
  await db('mobile_auth_attempts').del()
}

beforeAll(async () => {
  await db('agencies').insert({ id: AGENCY, name: '__test_mobile_email__' }).onConflict('id').ignore()
  const base = { agencyId: AGENCY, role: 'AGNT' as const, sessionVersion: 0, lastName: 'Tester' }
  await db('users')
    .insert([
      { id: USER_OK, firstName: 'Code', email: EMAIL_OK, emailVerifiedAt: new Date(), ...base },
      { id: USER_SUSPENDED, firstName: 'Susp', email: EMAIL_SUSPENDED, emailVerifiedAt: new Date(), suspended: true, ...base },
    ])
    .onConflict('id')
    .ignore()
})

beforeEach(async () => {
  sentEmails.length = 0
  await clearThrottle()
  await db('mobile_auth_codes').whereIn('email', [EMAIL_OK, EMAIL_SUSPENDED, EMAIL_STRANGER]).del()
  await db('mobile_refresh_tokens').whereIn('user_id', [USER_OK, USER_SUSPENDED]).del()
})

afterAll(async () => {
  await db('mobile_auth_codes').del()
  await clearThrottle()
  const strays = await db('users').where({ email: EMAIL_NEW_TENANT }).select('id', 'agencyId')
  for (const s of strays) {
    await db('mobile_refresh_tokens').where({ user_id: s.id }).del()
    await db('default_settings').where({ userId: s.id }).del()
    await db('users_info').where({ id: s.id }).del()
    await db('users').where({ id: s.id }).del()
    await db('agencies').where({ id: s.agencyId }).del()
  }
  await db('mobile_refresh_tokens').whereIn('user_id', [USER_OK, USER_SUSPENDED]).del()
  await db('users').whereIn('id', [USER_OK, USER_SUSPENDED]).del()
  await db('agencies').where({ id: AGENCY }).del()
  await db.destroy()
})

describe('email code — request', () => {
  it('sends a code to a real account', async () => {
    const { status } = await post('email/request', { email: EMAIL_OK })
    expect(status).toBe(204)
    expect(lastCodeFor(EMAIL_OK)).toMatch(/^\d{6}$/)
  })

  it('answers identically for an unknown address, and sends nothing', async () => {
    // The anti-enumeration property: same status, no mail, no account created.
    const before = Number((await db('users').count({ n: '*' }).first())?.n)
    const { status } = await post('email/request', { email: EMAIL_STRANGER })
    const after = Number((await db('users').count({ n: '*' }).first())?.n)

    expect(status).toBe(204)
    expect(sentEmails.find((m) => m.to === EMAIL_STRANGER)).toBeUndefined()
    expect(after).toBe(before)
  })

  it('answers identically for a suspended account, and sends nothing', async () => {
    const { status } = await post('email/request', { email: EMAIL_SUSPENDED })
    expect(status).toBe(204)
    expect(sentEmails.find((m) => m.to === EMAIL_SUSPENDED)).toBeUndefined()
  })

  it('stores only a hash — never the code itself', async () => {
    await post('email/request', { email: EMAIL_OK })
    const code = lastCodeFor(EMAIL_OK)
    const row = await db('mobile_auth_codes').where({ email: EMAIL_OK }).first('code_hash')

    expect(row.code_hash).not.toBe(code)
    expect(row.code_hash).toHaveLength(64)
  })

  it('supersedes an earlier live code', async () => {
    // Otherwise every code ever requested stays valid and the guess surface grows.
    await post('email/request', { email: EMAIL_OK })
    const first = lastCodeFor(EMAIL_OK)
    await post('email/request', { email: EMAIL_OK })

    expect((await post('email/verify', { email: EMAIL_OK, code: first })).status).toBe(401)
  })

  it('rejects a malformed body or an unexpected key', async () => {
    expect((await post('email/request', {})).status).toBe(400)
    expect((await post('email/request', { email: EMAIL_OK, userId: 1 })).status).toBe(400)
  })
})

describe('email code — verify', () => {
  it('exchanges a valid code for a mobile session', async () => {
    await post('email/request', { email: EMAIL_OK })
    const { status, body } = await post('email/verify', {
      email: EMAIL_OK,
      code: lastCodeFor(EMAIL_OK),
    })

    expect(status).toBe(200)
    expect(Object.keys(body).sort()).toEqual(['accessToken', 'refreshToken'])

    const row = await db('mobile_refresh_tokens').where({ user_id: USER_OK }).first('platform')
    expect(row.platform).toBe('ios')
  })

  it('leaks no internal field', async () => {
    await post('email/request', { email: EMAIL_OK })
    const { body } = await post('email/verify', { email: EMAIL_OK, code: lastCodeFor(EMAIL_OK) })
    const serialized = JSON.stringify(body)
    for (const forbidden of ['agencyId', 'idNum', 'sessionVersion', 'code_hash', EMAIL_OK]) {
      expect(serialized).not.toContain(forbidden)
    }
  })

  it('is single-use', async () => {
    await post('email/request', { email: EMAIL_OK })
    const code = lastCodeFor(EMAIL_OK)

    expect((await post('email/verify', { email: EMAIL_OK, code })).status).toBe(200)
    expect((await post('email/verify', { email: EMAIL_OK, code })).status).toBe(401)
  })

  it('rejects an expired code', async () => {
    await post('email/request', { email: EMAIL_OK })
    const code = lastCodeFor(EMAIL_OK)
    await db('mobile_auth_codes')
      .where({ email: EMAIL_OK })
      .update({ expires_at: new Date(Date.now() - 1000) })

    expect((await post('email/verify', { email: EMAIL_OK, code })).status).toBe(401)
  })

  it('burns the code after the attempt ceiling, so 10^6 cannot be walked', async () => {
    await post('email/request', { email: EMAIL_OK })
    const real = lastCodeFor(EMAIL_OK)
    const wrong = real === '000000' ? '111111' : '000000'

    for (let i = 0; i < MAX_CODE_ATTEMPTS; i += 1) {
      expect((await post('email/verify', { email: EMAIL_OK, code: wrong })).status).toBe(401)
    }

    // Even the CORRECT code is now dead — the budget belongs to the code, and
    // requesting a new one is the only way forward.
    expect((await post('email/verify', { email: EMAIL_OK, code: real })).status).toBe(401)
  })

  it('rejects a code for an address that never requested one', async () => {
    expect((await post('email/verify', { email: EMAIL_STRANGER, code: '123456' })).status).toBe(401)
  })

  it('validates the code shape before touching the database', async () => {
    expect((await post('email/verify', { email: EMAIL_OK, code: '12345' })).status).toBe(400)
    expect((await post('email/verify', { email: EMAIL_OK, code: 'abcdef' })).status).toBe(400)
    expect((await post('email/verify', { email: EMAIL_OK, code: 123456 })).status).toBe(400)
  })
})

describe('rate limiting', () => {
  it('stops mailbox flooding after the per-address ceiling', async () => {
    for (let i = 0; i < 5; i += 1) await post('email/request', { email: EMAIL_OK })
    const before = sentEmails.length

    // Still 204 — a throttled caller must not be able to tell.
    expect((await post('email/request', { email: EMAIL_OK })).status).toBe(204)
    expect(sentEmails.length).toBe(before)
  })

  it('records attempts against the email and the IP separately', async () => {
    await post('email/request', { email: EMAIL_OK })
    const rows = await db('mobile_auth_attempts').where({ kind: 'email_request' }).select('subject')
    const subjects = rows.map((r) => r.subject)

    expect(subjects).toContain(EMAIL_OK)
    expect(subjects.some((s) => s.startsWith('ip:'))).toBe(true)
  })

  it('never stores a credential as a throttle subject', async () => {
    await post('email/request', { email: EMAIL_OK })
    const code = lastCodeFor(EMAIL_OK)
    await post('email/verify', { email: EMAIL_OK, code })

    const rows = await db('mobile_auth_attempts').select('subject')
    expect(rows.every((r) => !r.subject.includes(code))).toBe(true)
  })
})

describe('native registration', () => {
  it('creates a complete tenant and returns a mobile session', async () => {
    const { status, body } = await post('register', {
      agencyName: 'Test Agency Ltd',
      firstName: 'New',
      lastName: 'Owner',
      email: EMAIL_NEW_TENANT,
    })

    expect(status).toBe(201)
    expect(Object.keys(body).sort()).toEqual(['accessToken', 'refreshToken'])

    const user = await db('users').where({ email: EMAIL_NEW_TENANT }).first('id', 'agencyId', 'role', 'emailVerifiedAt')
    expect(user.role).toBe('ADMIN')

    // All four rows, or the tenant is broken in a way nobody notices until later.
    expect(await db('agencies').where({ id: user.agencyId }).first()).toBeTruthy()
    expect(await db('users_info').where({ id: user.id }).first()).toBeTruthy()
    expect(await db('default_settings').where({ userId: user.id }).first()).toBeTruthy()

    // Signing up proves nothing about the mailbox.
    expect(user.emailVerifiedAt).toBeNull()
  })

  it('rejects a duplicate email without creating a partial tenant', async () => {
    const agenciesBefore = Number((await db('agencies').count({ n: '*' }).first())?.n)

    const { status, body } = await post('register', {
      agencyName: 'Another Agency',
      firstName: 'Dup',
      lastName: 'User',
      email: EMAIL_OK,
    })

    expect(status).toBe(409)
    expect(body.error.reason).toBe('email_taken')

    // THE ROLLBACK ASSERTION: the agency insert happens BEFORE the failing user
    // insert, so without a transaction this count would have grown.
    const agenciesAfter = Number((await db('agencies').count({ n: '*' }).first())?.n)
    expect(agenciesAfter).toBe(agenciesBefore)
  })

  it('requires every field the web form requires', async () => {
    const full = {
      agencyName: 'A',
      firstName: 'B',
      lastName: 'C',
      email: 'someone@example.test',
    }
    for (const key of Object.keys(full)) {
      const partial = { ...full } as Record<string, unknown>
      delete partial[key]
      expect((await post('register', partial)).status).toBe(400)
    }
  })

  it('refuses unexpected keys — no role or agencyId injection', async () => {
    const { status } = await post('register', {
      agencyName: 'X',
      firstName: 'Y',
      lastName: 'Z',
      email: 'inject@example.test',
      role: 'ADMIN',
    })
    expect(status).toBe(400)
  })
})
